82	  compose(state: ContactSceneState): SceneFromState {
83	    return {
84	      camera: {
85	        position: { ...state.camera.position },
86	        fov: state.camera.fov,
87	      },
88	      cameraTarget: {
89	        position: { ...state.camera.target },
90	      },
91	      [earthId]: state.earth,
92	      [rocketId]: state.rocket,
93	      [jetEngineId]: {
94	        position: { ...state.jetEngine.position },
95	        rotation: { ...state.jetEngine.rotation },
96	        scale: { ...state.jetEngine.scale },
97	        visible: state.jetEngine.visible,
