103	  apply(engine: Engine, state: ContactSceneState): void {
104	    engine.setState(this.compose(state));
105	    engine.getCamera().lookAt(engine.getCameraTarget().position);
106	    this._applyLight(engine, state.light);
107	    this._applyRocket(engine, state.rocket);
108	    this._applyJetEngine(engine, state.jetEngine);
109	    this._applyGravityBalls(engine, state.gravityBalls);
