112	  read(engine: Engine): ContactSceneState {
113	    const camera = engine.getCamera();
114	    const target = engine.getCameraTarget();
115	    const defaults = CONTACT_DEFAULT_SCENE_STATE;
116	    return {
117	      camera: {
118	        position: {
119	          x: this._toFinite(camera.position.x, defaults.camera.position.x),
120	          y: this._toFinite(camera.position.y, defaults.camera.position.y),
121	          z: this._toFinite(camera.position.z, defaults.camera.position.z),
122	        },
123	        target: {
124	          x: this._toFinite(target.position.x, defaults.camera.target.x),
125	          y: this._toFinite(target.position.y, defaults.camera.target.y),
126	          z: this._toFinite(target.position.z, defaults.camera.target.z),
127	        },
128	        fov: this._toFinite(camera.fov, defaults.camera.fov),
129	      },
130	      light: this._readLight(engine),
131	      earth: this._readTransform(engine, earthId, defaults.earth),
132	      rocket: this._readRocket(engine),
133	      jetEngine: this._readJetEngine(engine),
134	      gravityBalls: this._readGravityBalls(engine),
135	      terrian: this._readTransform(engine, terrianId, defaults.terrian),
136	    };
