154	        rig: {
155	          position: { ...value.light.rig.position },
156	          rotation: { ...value.light.rig.rotation },
157	          scale: { ...value.light.rig.scale },
158	          visible: value.light.rig.visible,
159	        },
160	      },
161	      earth: {
162	        position: { ...value.earth.position },
163	        rotation: { ...value.earth.rotation },
164	        scale: { ...value.earth.scale },
165	        visible: value.earth.visible,
166	      },
167	      rocket: {
168	        position: { ...value.rocket.position },
169	        rotation: { ...value.rocket.rotation },
170	        scale: { ...value.rocket.scale },
171	        visible: value.rocket.visible,
172	        flame: { ...value.rocket.flame },
173	      } as MainRocketState,
174	      jetEngine: {
175	        position: { ...value.jetEngine.position },
176	        rotation: { ...value.jetEngine.rotation },
177	        scale: { ...value.jetEngine.scale },
178	        visible: value.jetEngine.visible,
179	        intensity: value.jetEngine.intensity,
180	        length: value.jetEngine.length,
181	        nozzleRadius: value.jetEngine.nozzleRadius,
182	        nozzleGap: value.jetEngine.nozzleGap,
