213	  private _applyJetEngine(engine: Engine, state: MainJetEngineState): void {
214	    const jet = engine.getSceneObjectById(jetEngineId) as SceneObject<
215	      JetEngineTweenProps
216	    > | null;
217	    if (!jet || typeof jet.setTimelineVars !== "function") return;
218	    const { position: _p, rotation: _r, scale: _s, ...rest } = state;
219	    jet.setTimelineVars(rest, "to");
220	  }
221	
222	  private _applyGravityBalls(engine: Engine, state: MainGravityBallsState): void {
223	    const gb = engine.getSceneObjectById(gravityBallsId) as SceneObject<GravityBallsTweenProps> | null;
224	    if (!gb || typeof gb.setTimelineVars !== "function") return;
225	    gb.setTimelineVars(state, "to");
226	  }
