228	  private _readGravityBalls(engine: Engine): MainGravityBallsState {
229	    const defaults = CONTACT_DEFAULT_SCENE_STATE.gravityBalls;
230	    const object = engine.getSceneObjectById(gravityBallsId) as
231	      | { getRuntimeOptions?: () => Record<string, unknown> }
232	      | null;
233	    const runtime = object?.getRuntimeOptions?.() ?? {};
234	    return {
235	      visible: typeof runtime.visible === "boolean" ? runtime.visible : defaults.visible,
236	      dotsPerInterval: this._toFinite(runtime.dotsPerInterval, defaults.dotsPerInterval),
237	      physicsScale: this._toFinite(runtime.physicsScale, defaults.physicsScale),
238	      maxGravityBoost: this._toFinite(runtime.maxGravityBoost, defaults.maxGravityBoost),
239	      particleScaleMin: this._toFinite(runtime.particleScaleMin, defaults.particleScaleMin),
240	      particleScaleMax: this._toFinite(runtime.particleScaleMax, defaults.particleScaleMax),
241	    };
242	  }
243	
244	  private _readLight(engine: Engine): ContactSceneState["light"] {
245	    const light = engine.getSceneObjectById(
246	      aboutLightsId,
247	    ) as ContactLightsPort | null;
248	    if (!light) {
249	      const d = CONTACT_DEFAULT_SCENE_STATE.light;
250	      return {
251	        ...d,
252	        rig: {
253	          position: { ...d.rig.position },
254	          rotation: { ...d.rig.rotation },
255	          scale: { ...d.rig.scale },
256	          visible: d.rig.visible,
257	        },
258	      };
259	    }
260	    return light.getState();
261	  }
262	
263	  private _readRocket(engine: Engine): MainRocketState {
264	    const transform = this._readTransform(
265	      engine,
266	      rocketId,
267	      CONTACT_DEFAULT_SCENE_STATE.rocket,
268	    );
269	    const defaults = CONTACT_DEFAULT_SCENE_STATE.rocket;
270	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
271	    return {
272	      ...transform,
273	      flame: rocket?.getFlameState() ?? defaults.flame,
274	    } as MainRocketState;
275	  }
276	
277	  private _readJetEngine(engine: Engine): MainJetEngineState {
278	    const transform = this._readTransform(
279	      engine,
280	      jetEngineId,
281	      CONTACT_DEFAULT_SCENE_STATE.jetEngine,
282	    );
283	    const defaults = CONTACT_DEFAULT_SCENE_STATE.jetEngine;
284	    const object = engine.getSceneObjectById(jetEngineId) as
285	      | { getRuntimeOptions?: () => Record<string, unknown> }
286	      | null;
287	    const runtime = object?.getRuntimeOptions?.() ?? {};
288	    return {
289	      ...transform,
290	      intensity: this._toFinite(runtime.intensity, defaults.intensity),
291	      length: this._toFinite(runtime.length, defaults.length),
292	      nozzleRadius: this._toFinite(runtime.nozzleRadius, defaults.nozzleRadius),
293	      nozzleGap: this._toFinite(runtime.nozzleGap, defaults.nozzleGap),
294	      noise: this._toFinite(runtime.noise, defaults.noise),
295	      bloom: this._toFinite(runtime.bloom, defaults.bloom),
296	    };
297	  }
298	
299	  private _readTransform(
300	    engine: Engine,
301	    id: string,
302	    fallback: ContactTransformState,
303	  ): ContactTransformState {
304	    const target = engine.getObjectById(id) as THREE.Object3D | null;
305	    const rotation = Helpers.readRotationDeg(target);
306	    return {
307	      position: {
308	        x: this._toFinite(target?.position.x, fallback.position.x),
309	        y: this._toFinite(target?.position.y, fallback.position.y),
310	        z: this._toFinite(target?.position.z, fallback.position.z),
311	      },
312	      rotation: {
313	        x: this._toFinite(rotation.x, fallback.rotation.x),
314	        y: this._toFinite(rotation.y, fallback.rotation.y),
315	        z: this._toFinite(rotation.z, fallback.rotation.z),
316	      },
317	      scale: {
318	        x: this._toFinite(target?.scale.x, fallback.scale.x),
319	        y: this._toFinite(target?.scale.y, fallback.scale.y),
320	        z: this._toFinite(target?.scale.z, fallback.scale.z),
321	      },
322	      visible: target?.visible ?? fallback.visible,
323	    };
324	  }
325	
326	  private _toFinite(value: unknown, fallback: number): number {
327	    if (typeof value !== "number") return fallback;
328	    if (!Number.isFinite(value)) return fallback;
329	    return value;
330	  }
331	}
