1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import type { SceneObjectContext } from "../../types/engine.types.js";
4	import type {
5	  GravityBallsObjectOptions,
6	  GravityBallsTweenProps,
7	  SmokeFloorRuntime,
8	} from "../../types/object.types.js";
9	
10	interface SphereInfo {
11	  ID: number;
12	  startX: number;
13	  startY: number;
14	  startZ: number;
15	  spawnX: number;
16	  spawnY: number;
17	  vx: number;
18	  vy: number;
19	  vz: number;
20	  gravity: number;
21	  rotDir: number;
22	  shrinkRate: number;
23	  initScale: number;
24	  bounced: boolean;
25	  vxMult: number;
26	  vzMult: number;
27	  vyMult: number;
28	  sphere: THREE.Sprite;
29	  material: THREE.SpriteMaterial;
30	}
31	
32	type ResolvedOpts = {
33	  attachTo: string;
34	  spawnOffset: { x?: number; y?: number; z?: number };
35	  colors: string[];
36	  dotsPerInterval: number;
37	  physicsScale: number;
38	  proximityRange: number;
39	  maxGravityBoost: number;
40	  vxMult: number;
41	  vzMult: number;
42	  vyMult: number;
43	  particleScaleMin: number;
44	  particleScaleMax: number;
45	};
46	
47	const FADE_START_SCALE = 0.65;
48	const SMOKE_Z_DRIFT = 0.002;
49	const MAX_BALLS = 180;
50	const SMOKE_SPREAD = 1.005;
51	const DEFAULT_PARTICLE_SCALE_MIN = 1.2;
52	const DEFAULT_PARTICLE_SCALE_MAX = 3.0;
53	const LIFETIME_TICKS = 150;
54	const SMOKE_FLOOR_RUNTIME_KEY = "smokeFloor.runtime";
55	
56	const DEFAULT_TEXTURE_URLS = [
57	  "/resource/images/texture/smoke/smoke_01.png",
58	  "/resource/images/texture/rocket/smoke.png",
59	];
60	
61	const DEFAULTS = {
62	  attachTo: "rocket",
63	  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
64	  colors: ["#FFFFFF", "#F5F5F5", "#EEEEEE"] as string[],
65	  dotsPerInterval: 3,
66	  physicsScale: 0.006,
67	  proximityRange: 4.0,
68	  maxGravityBoost: 3.0,
69	  vxMult: 2.5,
70	  vzMult: 1.5,
71	  vyMult: -0.5,
72	  gravityBase: 10,
73	  floorLevel: -2.5,
74	  floorDimensions: 25,
75	};
76	
77	export class GravityBalls extends SceneObject<GravityBallsTweenProps> {
78	  private readonly _balls = new Map<number, SphereInfo>();
79	  private _idx = 0;
80	  private _accumMs = 0;
81	  private readonly _spawnPt = new THREE.Vector3();
82	  private _opts: GravityBallsObjectOptions = {};
83	  private _baseMats: THREE.SpriteMaterial[] = [];
84	
85	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
86	    if (props) this._opts = { ...this._opts, ...props };
87	    return this;
88	  }
89	
90	  protected override getOptions(): Record<string, unknown> {
91	    return this._opts as Record<string, unknown>;
92	  }
93	
94	  override async runObject(): Promise<void> {
95	    const ctx = this._context;
96	    if (!ctx) return;
97	
98	    const urls: string[] =
99	      this._opts.textureUrls?.length ? this._opts.textureUrls
100	      : this._opts.textureUrl ? [this._opts.textureUrl]
101	      : DEFAULT_TEXTURE_URLS;
102	
103	    const textures = await Promise.all(
104	      urls.map(async (url): Promise<THREE.Texture | null> => {
105	        if (!url || !ctx.loadTexture) return null;
106	        try { return await ctx.loadTexture(this.resolveAssetPath(url)); }
107	        catch { return null; }
108	      }),
109	    );
110	
111	    this._baseMats = textures.length > 0
112	      ? textures.map(tex => new THREE.SpriteMaterial({
113	          map: tex ?? null,
114	          transparent: true,
115	          depthWrite: false,
116	          opacity: 0.8,
117	        }))
118	      : [new THREE.SpriteMaterial({ transparent: true, depthWrite: false, opacity: 0.8 })];
119	
120	    this._applyOptionVisibility();
121	  }
122	
123	  override runUpdate(delta: number): void {
124	    const ctx = this._context;
125	    if (!ctx || this._disposed || !this.getVisibleState()) return;
126	
127	    this._accumMs += delta * 1000;
128	    if (this._accumMs >= 15) {
129	      this._accumMs -= 15;
130	      this._tick(ctx);
131	    }
132	  }
133	
134	  private _getFloorRuntime(): SmokeFloorRuntime | null {
135	    const candidate = this._context?.getObject(SMOKE_FLOOR_RUNTIME_KEY);
136	    if (candidate && typeof (candidate as unknown as SmokeFloorRuntime).getFloorY === "function") {
137	      return candidate as unknown as SmokeFloorRuntime;
138	    }
139	    return null;
140	  }
141	
142	  private _computeGravityScale(rocketY: number, floorY: number, o: ResolvedOpts): number {
143	    const dist = Math.max(0, rocketY - floorY);
144	    const t = 1 - Math.min(1, dist / o.proximityRange);
145	    return 1 + t * o.maxGravityBoost;
146	  }
147	
148	  private _tick(ctx: SceneObjectContext): void {
149	    const o = this._resolve();
150	
151	    if (o.attachTo) {
152	      const rkt = ctx.getObject(o.attachTo);
153	      if (rkt instanceof THREE.Object3D) {
154	        rkt.getWorldPosition(this._spawnPt);
155	        this._spawnPt.x += o.spawnOffset.x ?? 0;
156	        this._spawnPt.y += o.spawnOffset.y ?? 0;
157	        this._spawnPt.z += o.spawnOffset.z ?? 0;
158	      }
159	    }
160	
161	    const floorRuntime = this._getFloorRuntime();
162	    const floorY = floorRuntime?.getFloorY() ?? (this._opts.floorLevel ?? DEFAULTS.floorLevel);
163	    const floorDim = floorRuntime?.getFloorDimensions() ?? (this._opts.floorDimensions ?? DEFAULTS.floorDimensions);
164	    const gravityScale = this._computeGravityScale(this._spawnPt.y, floorY, o);
165	
166	    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o, gravityScale);
167	
168	    const dead: number[] = [];
169	    this._balls.forEach((b, id) => { if (this._step(b, floorY, floorDim)) dead.push(id); });
170	    for (const id of dead) this._balls.delete(id);
171	  }
172	
173	  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts, gravityScale: number): void {
174	    if (this._baseMats.length === 0 || this._balls.size >= MAX_BALLS) return;
175	
176	    const s = o.physicsScale;
177	    const baseMat = this._baseMats[Math.floor(Math.random() * this._baseMats.length)];
178	    const mat = baseMat.clone();
179	
180	    const color = o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0];
181	    mat.color.set(color);
182	    mat.rotation = Math.random() * Math.PI * 2;
183	
184	    const initScale = o.particleScaleMin + Math.random() * (o.particleScaleMax - o.particleScaleMin);
185	    const shrinkRate = -(initScale - 0.1) / LIFETIME_TICKS;
186	
187	    const isXNeg = this._rnd(0, 2) === 0;
188	    const isZNeg = this._rnd(0, 2) === 0;
189	
190	    const sprite = new THREE.Sprite(mat);
191	    sprite.scale.setScalar(initScale);
192	
193	    const info: SphereInfo = {
194	      ID: ++this._idx,
195	      startX: this._spawnPt.x,
196	      startY: this._spawnPt.y,
197	      startZ: this._spawnPt.z,
198	      spawnX: this._spawnPt.x,
199	      spawnY: this._spawnPt.y,
200	      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
201	      vy: this._rnd(-10, 10) * s,
202	      vz: isZNeg ? this._rnd(1, 26) * -0.4 * s : this._rnd(1, 26) * 0.4 * s,
203	      gravity: DEFAULTS.gravityBase * s * gravityScale,
204	      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
205	      shrinkRate,
206	      initScale,
207	      bounced: false,
208	      vxMult: o.vxMult,
209	      vzMult: o.vzMult,
210	      vyMult: o.vyMult,
211	      sphere: sprite,
212	      material: mat,
213	    };
214	
215	    ctx.scene.add(sprite);
216	    this._balls.set(info.ID, info);
217	  }
218	
219	  private _step(b: SphereInfo, floorY: number, floorDim: number): boolean {
220	    const sp = b.sphere;
221	
222	    sp.scale.x += b.shrinkRate;
223	    sp.scale.y += b.shrinkRate;
224	
225	    b.startX += b.vx * 0.6;
226	    b.startY -= b.vy * 0.5;
227	    b.startZ -= b.vz * 0.6;
228	    sp.position.x = b.startX;
229	    sp.position.y = b.startY;
230	    sp.position.z = b.startZ;
231	
232	    b.vy += b.gravity;
233	    b.material.rotation += b.rotDir;
234	
235	    const bounceY = floorY + sp.scale.x * 0.5;
236	    if (sp.position.y < bounceY) {
237	      sp.position.y = bounceY;
238	      b.startY = bounceY;
239	
240	      const inBounds =
241	        Math.abs(sp.position.x) < floorDim / 2 &&
242	        Math.abs(sp.position.z) < floorDim / 2;
243	
244	      if (!b.bounced) {
245	        b.vx *= b.vxMult;
246	        b.vz *= b.vzMult;
247	        if (inBounds) b.vy *= b.vyMult;
248	        b.bounced = true;
249	      } else {
250	        b.vx *= 0.92;
251	        b.vz *= 0.92;
252	        if (inBounds) b.vy *= b.vyMult;
253	      }
254	    }
255	
256	    if (sp.scale.y < FADE_START_SCALE) {
