136	  private readonly _registry = new Map<string, ObjectRegistrationSpec>();
137	  private readonly _configRuntime = new ObjectConfigRuntime();
138	  private _disposed = false;
139	  private static readonly _ENV_ALIAS_BY_OBJECT_ID: Readonly<
140	    Partial<Record<keyof ObjectOptionsByKey, string>>
141	  > = {
142	    [sceneLights]: "env.light",
143	  };
144	
145	  constructor(registry: ObjectFactoryRegistry = createDefaultRegistry()) {
146	    for (const [id, spec] of Object.entries(registry)) {
147	      this._registry.set(id, spec);
148	    }
149	  }
150	
151	  registerFactory(id: string, spec: ObjectRegistrationSpec): void {
152	    this._registry.set(id, spec);
153	  }
154	
155	  register(id: string, spec: ObjectRegistrationSpec): void {
156	    this.registerFactory(id, spec);
157	  }
158	
159	  async init(engine: Engine, pageConfig: PageConfig): Promise<void> {
160	    if (this._disposed) return;
161	    for (const [id, spec] of this._getEnabledSpecs(pageConfig)) {
162	      const object = this._createConfiguredObject(
163	        spec,
164	        pageConfig.objectOptions,
165	        pageConfig.initialState,
166	      );
167	      await engine.setObject(id, object);
168	      this._registerEnvironmentAlias(engine, id as keyof ObjectOptionsByKey);
169	    }
170	  }
